quests[41539] = { id = 41539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funkelnde Sternlichtrosen" }
quests[41540] = { id = 41540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit dem Kurier", description = "Thas'dorah ist in der Tat ein mächtiger Bogen! Die Waffe wurde aus einem Ast von Thas'talah, dem Mutterbaum des Immersangwalds, geschnitzt und mit der Magie des Sonnenbrunnens verstärkt. Talanas Windläufer führte diese Waffe, als wir zusammen die Invasion der Amanitrolle abwehrten.\n\nAh, aber für solche Geschichten ist jetzt keine Zeit.\n\nKurier Lerchensporn macht sich gerade bereit zur Abreise. Ihr könnt ihn an Krasus' Landeplatz treffen.", sourceObjective = "Sprecht mit Kurier Lerchensporn an Krasus' Landeplatz.", completion = "Ich kenne nicht alle Details, aber nach sehr langer Zeit haben wir jetzt dank eines Dämonengefangenen einen ersten soliden Hinweis auf den Aufenthaltsort von Alleria Windläufer erhalten.\n\nDie Waldläufergeneralin hat sich mit Mitgliedern der Weltenwanderer an der Verheerten Küste zusammengetan. Sie stellt gerade eine Einheit zusammen und Eure Beteiligung ist unabdingbar für den Erfolg.", sourceObjectiveStatus = "unverified-source-field" }
quests[41541] = { id = 41541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tierische Expedition", description = "Ich kenne die Macht von Titanenblitz sehr gut. Der Unsichtbare Pfad kämpfte einst gegen den Vrykulkriegsfürsten Volund, als er die Verheerten Inseln überfiel. Wir wollten ihm das Gewehr entreißen, aber er hat es mit in sein Grab genommen.\n\nWenn es jemandem gelänge, Volunds Grab zu öffnen und das Artefakt zu bergen, wäre das ein immenser Vorteil für uns.\n\nIch glaube, Grif Wildherz macht sich gerade zur Abreise bereit. Ihr könnt ihn an Krasus' Landeplatz treffen.", sourceObjective = "Sprecht mit Grif Wildherz an Krasus' Landeplatz in Dalaran.", completion = "Da seid Ihr ja! Wusste ich's doch, dass Ihr Titanenblitz unbedingt finden wollt.\n\nUnd macht Euch nichts aus dem alten Huey hier. Die Stadt der Magier ist kein geeigneter Ort für einen Greifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41542] = { id = 41542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung auf die Jagd", description = "Fangklaue ist ein wahrhaft mächtiger Speer! Ich habe ihn zum ersten Mal gesehen, als die Hochbergtauren die Mitglieder meines Ordens zum Krallengipfel führten, um die Volltrefferhütte zu finden.\n\nAber für solche Geschichten ist jetzt keine Zeit.\n\nApata hat in Dalaran ein paar Vorräte für ihre Expedition zusammengestellt. Sie müsste jetzt eigentlich bereit zur Abreise sein.\n\nSucht sie an Krasus' Landeplatz auf. Ich weiß, dass sie sicher sofort loslegen möchte.", sourceObjective = "Sprecht mit Apata Hochberg an Krasus' Landeplatz in Dalaran.", completion = "Es ist meinem Bruder Wuho und mir eine Ehre, dass Ihr uns auf dieser Expedition begleitet, {name}. Fangklaue gilt meinem Volk als heiliges Artefakt und ich weiß, dass wir ihn mit Eurer Hilfe bergen können.\n\nVor unserem Aufbruch ist nur noch eine Sache zu erledigen. Sprecht mit dem Adlergeist.", sourceObjectiveStatus = "unverified-source-field" }
