quests[41573] = { id = 41573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsbalg" }
quests[41574] = { id = 41574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerdiebstahl", description = "Titanenblitz befindet sich im Grab von Kriegsfürst Volund irgendwo auf der Schildruhinsel. Das ist ein sumpfiges Stück Eiland umgeben von düsteren Gewässern.\n\nKlingt doch gut, oder?\n\nIch habe mit einer Vrykulführerin namens Prustaga zusammengearbeitet. Sie wird uns helfen, die Zauberschutze aufzubrechen, die das Grab versiegelt halten.\n\nIch weiß, was Ihr denkt... Vrykul bedeuten Ärger. Aber Prustaga hat niemals versucht, mich anzugreifen.\n\nHuey wird uns runter zur Küste bringen. Prustaga hat das Grab wahrscheinlich schon gefunden!", sourceObjective = "Begleitet Grif Wildherz zur Schildruhinsel, um Titanenblitz zu finden.", completion = "Euch könnte ein wenig schwindelig sein, nachdem Ihr den Teleporter durchschritten habt. Die Verheerten Inseln sind schließlich nicht gerade nebenan.", sourceObjectiveStatus = "unverified-source-field" }
quests[41575] = { id = 41575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsseelenteleporter bereit!", description = "<Der telemantische Signalgeber ist deaktiviert, aber intakt. Mit etwas uraltem Mana sollte er bald wieder einsatzbereit sein.>", sourceObjective = "Reichert den Signalgeber mit uraltem Mana an.", progress = "<Der Signalgeber ist kalt und dunkel.>", completion = "<Der Signalgeber beginnt zu leuchten, als Ihr ihn mit uraltem Mana anreichert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[41582] = { id = 41582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiches Sonnenrennerleder" }
