quests[41605] = { id = 41605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebhafter Runenschuppenkoi" }
quests[41606] = { id = 41606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Brytag", description = "<Kell kann kaum sprechen.>\n\nDiese Nagahexe... hat viele meiner Leute... den Meeresriesen überlassen.\n\nBrytag habe ich... als Letzten noch lebend gesehen.\n\nFindet ihn schnell.", sourceObjective = "Sucht nach Brytag in der Azurwindbucht.", completion = "Ich weiß nicht, wer Ihr seid, doch Ihr seid kein Meeresriese. Das reicht mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[41607] = { id = 41607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promenadenaufmischung", description = "Wir müssen mehr über unsere lange verschollenen Verwandten erfahren, wenn wir erfolgreich gegen sie kämpfen wollen.\n\nWir haben einen unserer Späher entsandt, um die Promenade zu infiltrieren und Geheiminformationen zu beschaffen. Die Schildwachen haben ihre eigene Späherin entsandt. Ich hoffe, sie ist klug genug, sich nicht töten zu lassen, bevor sie Bericht erstatten kann.\n\nSie sind beide schon längst überfällig und wir müssen das Schlimmste befürchten.\n\nFindet sie, damit wir in Erfahrung bringen, womit wir es zu tun bekommen.", sourceObjective = "Findet die Späher auf der Promenade.", completion = "Sie sind am Leben? Das sind gute Neuigkeiten. Ihr Wissen über die Verteidigungen sind von unschätzbarem Wert.", sourceObjectiveStatus = "unverified-source-field" }
