quests[41617] = { id = 41617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewaltiger Runenschuppenkoi" }
quests[41618] = { id = 41618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meereswächter", description = "Der Meereswächter hat ein Abkommen mit der Gezeitenherrin abgeschlossen. Sie hat uns ihm ausgeliefert, als wären wir Vieh.\n\nIch hasse diesen Meeresriesen! Wenn ich nicht in dieser Blase gefangen wäre, würde ich ihn eigenhändig erwürgen.\n\nFalls Ihr ihm begegnet, bevor ich hier herauskomme, dann sorgt dafür, dass er seinen Pakt mit den Naga gründlich bereut!", sourceObjective = "Tötet Meereswächter Largush in der Azurwindbucht.", progress = "Habt Ihr den Meereswächter getötet?", completion = "Ich wünschte nur, ich hätte ihn zuerst in die Finger bekommen.\n\nPah! Jetzt kann er von mir aus in diesen Gewässern verfaulen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41622] = { id = 41622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbe der Scharrfurien" }
quests[41623] = { id = 41623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions vom Hochberg" }
quests[41624] = { id = 41624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocko muss rasiert werden", sourceObjective = "Besiegt Rocko in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[41625] = { id = 41625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Lichts", description = "Der Zorn des Lichts... eine riskante Wahl. Doch wenn Ihr der Meinung seid, dass Ihr seine Energie kontrollieren könnt, könnte er für unsere Sache entscheidend sein.\n\nIhn zu beschaffen, wird aber nicht leicht. Zuletzt befand er sich im Besitz der Kirin Tor. Diese fürchteten sich vor seiner ungezügelten Macht und übergaben ihn dem blauen Drachenschwarm, der ihn vor den Menschen bewahren sollte. Nur der Schwarm weiß genau, wohin er gebracht wurde und wie man ihn zurückholen kann.\n\nDer Drache Kalec stellt vermutlich unsere beste Chance dar. Er ist Mitglied im Rat der Sechs von Dalaran. Sucht dort nach ihm... und nach Antworten.", sourceObjective = "Trefft Kalec in der Violetten Zitadelle in Dalaran.", completion = "Ihr sucht nach dem Zorn des Lichts? Eine wirklich gefährliche Waffe.\n\nVor langer Zeit überließen die Kirin Tor ihn dem blauen Drachenschwarm. Diese verwahrten ihn an dem einzigen Ort, der seiner ungezügelten Macht standhalten konnte: in der Nexuskammer.\n\nIch war allerdings schon lange nicht mehr dort. Nachdem sich der blaue Drachenschwarm aufgelöst hatte, wurde der Nexus aufgegeben. Wir können nicht mit Sicherheit sagen, ob die Nexuskammer noch intakt ist... oder was einen im Nexus selbst erwarten könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[41626] = { id = 41626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Bedrohung", description = "Wenn Ihr den Nexus sucht, solltet Ihr nichts überstürzen. In Kaltarra gehen seltsame Dinge vor sich und es wäre sinnvoll, einige Informationen zu sammeln, bevor Ihr weitermacht.\n\nWährend meines letzten Besuchs der Drachenöde spürte ich ungewöhnliche Energien vom Azurdrachenschrein ausgehen. Da dieser Ort eng mit Malygos' Plänen während der Nexuskriege in Verbindung stand, könnte die Situation an diesem Ort Rückschlüsse auf den derzeitigen Zustand des Nexus ermöglichen.\n\nIch kann Euch nicht begleiten, doch mit diesem Kristall könnt Ihr mich erreichen. Viel Glück.", sourceObjective = "Sucht am Azurdrachenschrein nach Hinweisen auf den derzeitigen Zustand des Nexus.", progress = "Das Kommunikationsgerät ist inaktiv.", completion = "Dies ist offenbar ein Kommunikationsmittel, das häufig von den Astralen genutzt wurde.\n\nMöglicherweise könnt Ihr damit herausfinden, was hinter den Ereignissen am Drachenschrein steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41627] = { id = 41627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vergessener Feind", description = "Das Gerät summt noch immer vor Energie. Es muss vor Kurzem benutzt worden sein.\n\nEs wird wohl mit dem Schalter in der Nähe aktiviert.", sourceObjective = "Aktiviert das Kommunikationsgerät der Astralen am Azurdrachenschrein.", sourceObjectiveStatus = "unverified-source-field" }
quests[41628] = { id = 41628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Drachen", description = "Ihr solltet Euch gleich nach Kaltarra in der Boreanischen Tundra begeben, {name}. Ich empfehle, dass Ihr dort ein paar bedeutende Orte auskundschaftet und mich entsprechend informiert.\n\nIch kenne das Gebiet gut und sollte Euch anleiten können.\n\nBeeilt Euch!", sourceObjective = "Erkundet die wichtigen Orte in Kaltarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[41629] = { id = 41629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigung des heiligen Feuers", description = "Die Energie des Zorns des Lichts peitscht aus dem Inneren der geschwächten Nexuskammer heraus. Vielleicht gelingt es uns, diese rohe, chaotische Energie für unsere Zwecke zu nutzen.\n\nWenn wir die Energie in die Sognadeln speisen können, sollte dies zu einer recht... zerstörerischen Reaktion führen.", sourceObjective = "Ermächtigt Euch mit instabiler heiliger Energie, indem Ihr Zorngebilde des Lichts besiegt oder sie aus Rissen heiliger Energie entlang des Nexusfundaments entzieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41630] = { id = 41630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Gerechtigkeit", description = "Ihr verfügt über die notwendige Macht, um die Sognadeln zu vernichten.\n\nBei den Rissen, an denen die Sognadeln im Boden stecken, gibt es große Ansammlungen von Leerenenergie. Konzentriert die Macht des Zorns des Lichts auf diese Stellen fokussierter Leere. Die Reaktion sollte zur Überladung führen und die darüberliegenden Sognadeln vernichten.\n\nIhr müsst schnell handeln. Das Astraleum wird sicher nicht untätig zusehen, während Ihr ihren Machenschaften ein Ende setzt.", sourceObjective = "Nutzt Eure gesammelte instabile heilige Energie, um die Sognadeln in Kaltarra zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[41631] = { id = 41631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nexuskammer", description = "Wenn das Astraleum es geschafft hat, Azuregos gefangen zu nehmen, ist es noch mächtiger, als ich befürchtet hatte.\n\nAzuregos und ich waren zwar nicht immer einer Meinung, aber wir sind Brüder. Da Ihr den Astralen ein Ende setzen und den Zorn des Lichts an Euch bringen wollt, möchte ich Euch bitten, darüber hinaus auch meinen Bruder aus ihren Klauen zu befreien.\n\nJetzt, da die Sognadeln vernichtet sind, hat der Schild sich aufgelöst. Der Nexus wartet, {name}.", sourceObjective = "Besiegt Nexusprinz Bilaal und beansprucht den Zorn des Lichts für Euch.", completion = "Ich danke Euch für Azuregos' Rettung, {name}. In dem Wissen, dass der Nexus von ihm behütet wird, kann ich nun Ruhe finden.\n\nWas Euch angeht, so seid Ihr immer für eine Überraschung gut. In all meiner Zeit habe ich keinen {class} gesehen, der die chaotischen Energien des Zorns des Lichts kontrollieren konnte.\n\nIhr seid wahrlich der Held, der uns in den Kampf gegen die Legion führen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[41632] = { id = 41632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk der Zeit", description = "Am heutigen Tage habt Ihr den blauen Drachen einen großen Dienst erwiesen, {name}. Und auch ich habe meinen Seelenfrieden zurückgewonnen.\n\nJetzt, da ihr den Zorn des Lichts besitzt, bitte ich Euch, Euer ursprüngliches Ziel zu verfolgen und gegen die Legion in den Kampf zu ziehen.\n\nIch glaube, Alonsus Faol erwartet Eure Rückkehr. Möge Eure Reise sicher verlaufen.", sourceObjective = "Sprecht mit Alonsus Faol.", completion = "Also haben sich die Drachen als hilfreich erwiesen? Das ist gut, denn wir werden wohl ihre Unterstützung im kommenden Krieg benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41633] = { id = 41633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Leysteinbeinschützer", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Schmied. Wir haben diese Schienbeinschützer wirklich dringend gebraucht." }
