quests[41689] = { id = 41689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigung des Mutterbaums", description = "Wir müssen den Mutterbaum retten, koste es, was es wolle.\n\nIch glaube, ich weiß auch schon wie.\n\nDer Weltenbaum Nordrassil auf dem Hyjal entstand aus einer Eichel von G'Hanir. Wir können das heilige Wasser an dessen Wurzeln nutzen, um die Verderbnis zu läutern.\n\nWenn wir dem Traumpfad zum Gipfel des Hyjal folgen, sollte uns genug Zeit bleiben, um das Läuterungsritual durchzuführen, bevor G'Hanir gänzlich der Dunkelheit erliegt.", sourceObjective = "Nutzt den Traumpfad, um zum Hyjal zu reisen, und läutert G'Hanir in den heiligen Wassern unter Nordrassil.", completion = "Für Euren Heldenmut sind wir Euch viel schuldig, {name}. Ich selbst bin Euch viel schuldig.\n\nDoch ich vermute, dieser Krieg ist noch lange nicht vorbei.", sourceObjectiveStatus = "unverified-source-field" }
quests[41690] = { id = 41690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneutes Zusammentreffen", description = "Ihr habt Lyessa im Traum gefunden, nicht wahr, Shan'do {name}? Ich hörte Euch ihren Namen im Schlaf murmeln.\n\nElune sei Dank, dass es ihr gut geht.\n\nIhr müsst sie aufsuchen. Ich kann ihre Gegenwart sogar jetzt noch am Kreis der Geister über uns wahrnehmen.\n\nWenn es irgendjemanden gibt, der uns helfen kann, G'Hanir zu läutern, dann ist es Lyessa.", sourceObjective = "Trefft Euch mit Lyessa Blütenseher am Kreis der Geister.", completion = "Ich weiß nicht, wie lange ich noch ausgehalten hätte, wenn Ihr nicht gekommen wärt. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[41691] = { id = 41691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Meer aus Federn" }
