quests[41701] = { id = 41701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerjäger" }
quests[41702] = { id = 41702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Stein gemeißelt", description = "<Ihr bündelt die Notizen und steckt sie in Euren Rucksack.\n\nDem letzten Tagebucheintrag zufolge hat Kel'danath für seine Experimente etwas genutzt, das er als \"Zauberstein\" bezeichnet.\n\nDer Zauberstein, wenn nicht sogar der Arkanist selbst, sollte sich in der Nähe befinden.>", sourceObjective = "Beschafft den Zauberstein von Kel'danath.", progress = "<Dieser Verdorrte scheint von dem Zauberstein betört zu sein. Er ist völlig befriedet.>", completion = "<Auf einem kleinen Anhänger an seinem Ärmel steht: \"16 - Theryn\".>", sourceObjectiveStatus = "unverified-source-field" }
quests[41703] = { id = 41703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Ormagrogg" }
quests[41704] = { id = 41704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subjekt 16", description = "<Theryn scheint noch immer unter dem Zauber des Arkanisten zu stehen. In Kel'danaths Abwesenheit könnte ein lebendes Versuchsobjekt Thalyssra dabei helfen, seine Forschung nachzuvollziehen.>", sourceObjective = "Bringt Theryn zu Thalyssra.", completion = "Kel'danath hat sich also letztendlich verwandelt...\n\nDas hatte er nicht verdient. Danke, dass Ihr ihm ermöglicht habt, Ruhe zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41705] = { id = 41705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Donnertotem" }
quests[41706] = { id = 41706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salziges Gewässer" }
quests[41707] = { id = 41707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurmkrallentrümmer", description = "Als ob Shaladrassils sich nähernde Wurzeln noch nicht reichen würden, wollen jetzt die Wurmkrallenharpyien auch noch unsere Misere ausnutzen.\n\nTötet sie, {race}. Das verdienen sie dafür, dass sie sich an unserem Elend weiden.", sourceObjective = "Tötet 15 Wurmkrallenharpyien im Schattenmoor.", completion = "Solche Gewalt sollte eigentlich nicht notwendig sein. Dennoch danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[41708] = { id = 41708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkle Seite des Mondes", description = "Xavius hat Ysera hier entlanggeführt, doch wohin sie gezogen sind, ist nicht ganz klar. Diese widerwärtige Verderbnis vernebelt mir die Sinne!\n\nDiese Flüchtlinge haben von einem uralten Mondbrunnen gesprochen, der in den Ruinen ihrer Heimat verborgen liegt. Vielleicht konnte er ja dieser Verderbnis widerstehen...\n\nIch werde Elune anflehen, mir eine richtungsweisende Vision zu schenken. Mit ihrem Licht kann ich meinen Gatten vielleicht immer noch finden.", sourceObjective = "Beschützt Tyrande, während sie am uralten Mondbrunnen ihre Wache hält.", completion = "Er lebt noch, aber alles Weitere müssen wir erst in Erfahrung bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41709] = { id = 41709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Geschütze zur Selbstmontage", description = "Ihr habt Euch gegen diese Meereshexe gut geschlagen, doch das reicht nicht.\n\nIhre Macht ist weit größer als die aller Kreaturen, gegen die ich je gekämpft habe. Wir brauchen etwas Großes, um sie zu besiegen. Etwas, mit dem sie nicht rechnet...\n\n<Toryl grinst.>\n\nEtwas, das die Naga selbst erdacht haben...\n\nSammelt so viele Teile ihrer Harpunenschleudern wie möglich und kommt dann wieder zu mir nach Jandvik.", sourceObjective = "Sammelt 50 Harpunenteile von Harpunieren der Sashj'tar in der Azurwindbucht.", progress = "Die Gezeitenherrin ist eine gefährliche Gegnerin. Wir müssen genauso listig sein, wenn wir sie besiegen wollen.", completion = "Ihr habt alle Teile, die Ihr brauchen werdet... von manchen sogar zwei.", sourceObjectiveStatus = "unverified-source-field" }
quests[41710] = { id = 41710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 A" }
