quests[41723] = { id = 41723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legion 110 H" }
quests[41724] = { id = 41724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Alptraums", description = "Ich weiß lediglich, dass mein Gatte irgendwo tiefer in diesem entstellten Wald steckt. Er ist noch am Leben, aber ob er unversehrt ist, ist ungewiss.\n\n<Tyrandes Gesichtsausdruck verhärtet sich zu einem finsteren Blick.>\n\nWenn er es nicht ist, wird nicht einmal Elune Xavius beschützen können.", sourceObjective = "Folgt Malfurions Pfad durch den Alptraum.", completion = "Vor dieser Verderbnis ist niemand sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[41728] = { id = 41728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung des Tianklosters", description = "Laut Chens letztem Bericht wird das Tiankloster angegriffen!\n\nSie brauchen Eure Hilfe, {name}. Sprecht mit Tak-Tak westlich des Haupttempels. Er kann Euch umgehend dorthinbringen.", sourceObjective = "Reist zum Jadewald von Pandaria und sprecht mit Taran Zhu am Tiankloster. Bittet Tak-Tak im Westen des Tempels der Fünf Sonnenaufgänge, Euch dorthinzufliegen.", completion = "Ich hätte nicht erwartet, den Großmeister höchstpersönlich zu sehen! Eure Stärke wird uns dabei helfen, das Blatt zu wenden. Wir dürfen nicht zulassen, dass die Dämonen Erfolg haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[41729] = { id = 41729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbreitung verlangsamen", description = "Verstärkung. Die haben wir auch nötig! <Großmeister/Großmeisterin>, das Kloster wird angegriffen.\n\nDie Legion setzt ein schreckliches Gerät namens Teufelskondensator ein, um den Boden unter unseren Füßen mit widerwärtiger Teufelsenergie zu verseuchen.\n\nZerstört diese Maschinen, damit wir ihnen Einhalt gebieten können.", sourceObjective = "Zerstört 3 Teufelskondensatoren.", completion = "Ihr habt wohlgetan, kleiner Wicht. Bleibt gemeinsam stark, das führt zum Licht! Der Feind wollte Verderbnis verbreiten, doch wir konnten seinen Untergang einleiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[41730] = { id = 41730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Kraft der Verzweiflung", description = "Sehr gut. Ihr kommt genau zur rechten Zeit, {name}.\n\nDiese widerwärtigen Legionskreaturen haben unser Zuhause überrannt. Sie haben nichts auf dieser Welt verloren.\n\nTötet alle Dämonen, denen Ihr begegnet, <Bruder/Schwester>.", sourceObjective = "Tötet 20 Dämonenangreifer.", completion = "Guter Nappel, starker Nappel, für die Hilfe vielen Dank! Ihr habt Dämonen weggejagt, nun sind sie schwach und krank!", sourceObjectiveStatus = "unverified-source-field" }
quests[41731] = { id = 41731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm, Erde und Feuer", description = "Das Tiankloster ist schwer mitgenommen.\n\nDie Teufelskondensatorwichtel versengen den Boden. Teufelsstacheln strahlen widerwärtige Teufelsenergie aus und verseuchen die Umgebung. Und diese Teufelsmagie ist sogar in die Bierfässer des Klosters eingesickert und hat das Gebräu besudelt.\n\nSetzt Eure Fähigkeiten ein, um die Flammen zu löschen, die Stacheln zu zerschmettern und die besudelten Fässer zu zerstören.\n\nSeufz... Ganze Jahrhunderte feinster Braukunst... alles dahin.\n\nIch möchte nicht mehr darüber sprechen. Sorgt einfach dafür, dass es geschieht.", sourceObjective = "Zerstört 5 Teufelsstacheln, löscht 5 Teufelsfeuer und zerstört 5 besudelte Bierfässer.", progress = "Ist es vollbracht?", completion = "Dank Euch ist das Gelände jetzt sicher, wie ich mich freu... nur schade, dass wir nichts retten konnten von dem Gebräu!\n\n<Der Affenkönig seufzt tief.>", sourceObjectiveStatus = "unverified-source-field" }
quests[41732] = { id = 41732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand von Keletress", description = "Der Dämonenanführer ist gleich voraus... und er macht Gefangene, welch ein Graus!\n\nGemeinsam überstehen wir den Sturm, gemeinsam bekämpfen wir den Wurm!", sourceObjective = "Tötet Skola Großschwert.", completion = "Dank Euch ist das Tiankloster wieder sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[41733] = { id = 41733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederaufbau des Ordens", description = "Im Namen aller Schüler und Lehrer des Tianklosters möchte ich Euch danken, <Großmeister/Großmeisterin> {name}.\n\nMit dem Wiederaufbau unseres Ordens habt Ihr eine schwere Aufgabe übernommen, aber wir werden Euch unterstützen.\n\nLasst uns zurück zur Wandernden Insel reisen.", sourceObjective = "Sprecht mit Eisenkörper Ponshu auf der Wandernden Insel.", completion = "Dank Euch wird unser Orden weiter Schüler unterweisen können, Großmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[41734] = { id = 41734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Taran Zhu", sourceObjective = "Großmeister, die legendären Geschichten über Euch waren nicht übertrieben. Ich selbst habe Eure Heldentaten am Tiankloster miterleben dürfen.\n\nIch habe mich mit Leib und Seele dem Mönchsorden verschrieben, und vor uns liegen noch viele Schlachten.\n\nLasst mich bitte für Euch kämpfen. Es wäre mir eine Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[41735] = { id = 41735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Der Affenkönig", sourceObjective = "Gemeinsam kämpften wir, oh Ihr Gewitzter, welch Wonne, um zu verteidigen den Tempel der Aufgeh'nden Sonne.\n\nAls geborener Anführer habt Ihr alle vereint, ich bin viel lieber Euer Freund als Euer Feind!\n\nIn den Ring werf ich meinen Hut! Lasst mich für Euch kämpfen, das wird gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[41736] = { id = 41736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Angus Eisenfaust", sourceObjective = "Es war eine Ehre, Euch kämpfen sehen zu dürfen, Großmeister {name}. Ich bin so entschlossen wie nie, Lady Keletress und die Legionstruppen auszulöschen.\n\nIch glaube, wir können das Sturmgebräurezept der Vrykul verwenden, um unser eigenes Gebräu herzustellen und so ihre eigene Waffe gegen sie selbst einzusetzen.\n\nWerdet Ihr mich an Eurer Seite kämpfen lassen?", sourceObjectiveStatus = "unverified-source-field" }
quests[41737] = { id = 41737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hiro", sourceObjective = "Ah, fühlt sich gut an, wieder in Sicherheit zu sein.\n\nNach dem Genuss von ein paar Gebräuen fühle ich mich doch gleich viel besser.\n\nIch verdanke Euch mein Leben, Großmeister. Ich gelobe Euch ewige Treue. Ich werde Euch jeden Wunsch erfüllen, Ihr müsst ihn nur aussprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41738] = { id = 41738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Sylara Stahlsang", sourceObjective = "<Sylara blickt durch die offene Tür gen Himmel. Sie scheint in Gedanken verloren, als würde sie über eine andere, unerledigte Aufgabe nachdenken. Sie stößt einen kaum hörbaren Seufzer aus.>\n\n<Dann aber heftet sich ihr entschlossener Blick auf Euch.>\n\nMein Platz ist an Eurer Seite.\n\nIch werde für Euch kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41739] = { id = 41739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Aegira", sourceObjective = "Wir haben viel zusammen durchgemacht, {name}.\n\nOhne Eure Hilfe hätte ich nicht den Mut und die Kraft gehabt, meine Meisterin zu rächen und ihr legendäres Gebräu erneut herzustellen.\n\nDank Euch haben wir jetzt genug Sturmgebräu für den gesamten Tempel.\n\nDabei ist mir auch aufgefallen, dass unsere Kampfstile recht ähnlich zu sein scheinen.\n\nWürdet Ihr mich als nächstes Mitglied Eures Ordens aufnehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[41740] = { id = 41740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bisschen aufrüsten, bitte", description = "Es gibt viele Wege, mit den Elementen zu kommunizieren. Die genialen Goblins haben Wege gefunden, ihre mechanischen Geräte mit der Energie von Elementargeistern zu versehen. Ich gebe nicht vor, das zu verstehen. Aber in dieser Stunde unserer Not dürfen wir keine Optionen außer Acht lassen.\n\nWir können uns glücklich schätzen, dass jemand namens \"Goldmine\" in unseren Diensten steht, dessen unorthodoxe Forschung unsere Kräfte vielleicht erheblich stärkt. Er wartet in der Nähe.", sourceObjective = "Sprecht mit dem Gesellen Goldmine im Herz von Azeroth im Mahlstrom.", completion = "Ausgezeichnete Wahl, Scharfseher. Schamanen aus der ganzen Welt können viel voneinander lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41741] = { id = 41741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen im Feld", description = "Es ist Zeit, die Stärke Eurer neu herbeigerufenen geringen Elementare zu testen. Betrachtet die Späherkarte und entsendet Eure Champions und Trupps auf eine Routineerkundungsmission.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Truppen im Feld\" ab.", completion = "Die Aufklärungsmission war noch erfolgreicher, als wir erwartet hatten, {name}. Eure Truppen konnten den Gesellen Goldmine retten, einen... äußerst ungewöhnlichen kleinen Schamanen.\n\nZum Dank hat er angeboten, uns zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41742] = { id = 41742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Celestos", sourceObjective = "Der Windlord hat mir befohlen, den Irdenen Ring bei seiner Kampagne gegen die Brennende Legion zu unterstützen.\n\nLord Donneraan erkennt großes Potential in Euch, Scharfseher. Als Dank für Eure Hilfe bei seiner Rückkehr als Windlord hat er Euch meine Dienste hier im Reich der Sterblichen gewährt.\n\nWenn die Zeit für den Kampf näherrückt, werden die Armeen des Himmelswalls hinter Euch stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41743] = { id = 41743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nobundo", sourceObjective = "Als Anführer seid Ihr in dieser Zeit der Krise eine Inspiration gewesen, Scharfseher {name}. Es war wirklich eine Ehre, mit Euch gemeinsam diese Reise durch den Himmelswall zu unternehmen.\n\nObwohl es hier viele Dinge gibt, die meiner Aufmerksamkeit bedürfen, wäre es mir eine Ehre, erneut an Eurer Seite zu kämpfen.\n\nSolltet Ihr also meine Hilfe jemals wieder benötigen, könnt Ihr über mich verfügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41744] = { id = 41744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Rehgar Erdenwut", sourceObjective = "Ich habe Euch immer für Euren Kampfesmut bewundert, Scharfseher.\n\nDie Art und Weise, wie Ihr Euch für den Irdenen Ring eingesetzt und die Elementarlords geeint habt... Es war eine Ehre, das mitanzusehen. Ihr seid wahrlich ein großartiger Anführer. Ein Anführer, wie unser Orden ihn braucht!\n\nObwohl die Elemente sich gegen die Brennende Legion zusammengeschlossen haben, ist unsere Arbeit noch nicht vollbracht. Solltet Ihr meine Fähigkeiten erneut benötigen, braucht Ihr nur zu fragen.\n\nIch lebe, um dem Irdenen Ring zu dienen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41745] = { id = 41745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Scaldius", sourceObjective = "Der Feuerlord hat mir befohlen, den Sterblichen in ihrem Kampf gegen die Brennende Legion beizustehen.\n\nMein Meister hat entschieden, dass die dämonischen Eindringlinge keinen Platz in dieser Welt haben. Ich lebe dafür, die Feinde meines Meisters zu vernichten.\n\nIch werde Euren Befehlen gehorchen, als ob sie vom Feuerlord selbst stammten. Wen soll ich als Erstes vernichten?", sourceObjectiveStatus = "unverified-source-field" }
quests[41746] = { id = 41746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Muln Erdenwut", sourceObjective = "Es war eine Ehre, in Tiefenheim an Eurer Seite zu kämpfen, Scharfseher. Die Art, wie Ihr unseren Orden mit Mut und Entschlossenheit anführt, erfüllt uns alle mit Hoffnung.\n\nTrotzdem fürchte ich, dass uns das Schlimmste noch bevorsteht. Ihr solltet diese Last nicht alleine tragen.\n\nGewährt mir die Ehre, erneut an Eurer Seite kämpfen zu dürfen, und ich werde Euch nicht enttäuschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41747] = { id = 41747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lavinius", sourceObjective = "<Die langsam gesprochenen Worte von Lavinius erreichen Euch mit einem tiefen Grollen.>\n\nSteinmutter... hat mich geschickt, um Scharfseher zu helfen...\n\nSagt, Dämonen zerschmettern... Schamanen beschützen.\n\n<Lavinius schlägt seine riesigen Steinfäuste gegeneinander, was den Raum erbeben lässt.>\n\nLavinius geht mit Scharfseher... lässt Dämonen weinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41748] = { id = 41748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ritssyn Flammengroll", sourceObjective = "Wir müssen den Rat neu aufbauen, wenn wir die Legion vernichten wollen. Aber diese Aufgabe kann niemand allein bewältigen.\n\nIhr könntet jemanden an Eurer Seite brauchen, der etwas über die schwere Last der Befehlsgewalt weiß.\n\nIch würde mich geehrt fühlen, Euch mit Rat und Tat zu dienen. Mit Eurer Kraft und unter Eurer Führung schaffen wir den Wiederaufbau.", sourceObjectiveStatus = "unverified-source-field" }
quests[41749] = { id = 41749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderbnis überlassen", description = "Dürfte ich Euch um einen letzten Gefallen bitten? Varethos, ein sehr alter Freund von mir, ist den Qualen des Alptraums zum Opfer gefallen. Wir haben einst zusammen dieses Land beschützt. Seine enge Verbundenheit mit ebendiesem ist ihm jetzt zum Verhängnis geworden.\n\nWie bei den anderen Opfern gibt es auch für ihn keine Hoffnung mehr.\n\nIch bitte Euch, {name}, sorgt dafür, dass er Frieden findet.", sourceObjective = "Tötet Hüter Varethos.", completion = "Mein Blick verschwimmt, doch ich freue mich, dass er Ruhe gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[41750] = { id = 41750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Calydus", sourceObjective = "Calydus leidet dank Freund nicht mehr unter grausamer Hand von Jagganoth.\n\nCalydus hat die Wahl, wem er folgen will. Er schwört dem neuen Oberanführer die Treue!\n\nVorausgesetzt, Freund lässt Calydus helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[41751] = { id = 41751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kira Zornseele", sourceObjective = "Ihr habt Euch wirklich mit Leib und Seele dem Wiederaufbau des Rates verschrieben. Ihr hättet Shinfel sterben lassen und einfach einen Ersatz suchen können, aber Ihr lasst Eure Verbündeten nicht im Stich.\n\nEinst bin ich blind gefolgt und habe darauf vertraut, dass mein Mentor nur das Beste für mich will. Stattdessen verließ er mich, um einen Rat zu führen, der mich für meine Arbeitsweise tadelte.\n\nDeshalb werde ich niemandes Anhängerin sein. Stattdessen werde ich an Eurer Seite stehen. Setzt meine Macht nach Eurem Gutdünken ein, wenn Ihr das wünscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41752] = { id = 41752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Zinnin Smythe", sourceObjective = "<Zinnin blickt Euch in die Augen, während er schweigend und nachdenklich dasteht. Er hält den Blickkontakt aufrecht, während er seine Faust zu seiner Brust führt und somit einen stillen Schwur leistet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[41753] = { id = 41753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Jubeka Schattenbrecher", sourceObjective = "Wir müssen aufhören, uns unter solchen Umständen zu treffen, {name}. Ihr habt mich öfter gerettet, als ich zugeben möchte.\n\nFalls Ihr jedoch selbst einmal gerettet werden müsst, erwidere ich den Gefallen nur zu gern.", sourceObjectiveStatus = "unverified-source-field" }
quests[41754] = { id = 41754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Shinfel Pestschwur", sourceObjective = "Also hat Ritssyn Euch zum Ersten unseres Rates gemacht, ja?\n\nAnscheinend hat sich in der kurzen Zeit, in der ich fort war, vieles verändert.\n\nDie Bedrohung durch die Legion ist größer als je zuvor. Ich habe ihre Macht mit eigenen Augen gesehen und weiß, dass wir sie in unserem momentanen Zustand nicht besiegen können.\n\nIhr werdet uns einen, {name}, und gemeinsam werden wir die Legion ihrer Macht berauben!", sourceObjectiveStatus = "unverified-source-field" }
quests[41755] = { id = 41755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lulubell Zischknall", sourceObjective = "Ich muss mich nicht mehr schamvoll verstecken. Das habe ich Euch zu verdanken.\n\nDiese Schuld werde ich wohl nie begleichen können, aber ich würde es gerne versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41756] = { id = 41756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Eredarzwillinge", sourceObjective = "Wir leben, um Euch zu dienen, {name}.\n\nMit Freuden erfüllen wir jeden Eurer Wünsche.", sourceObjectiveStatus = "unverified-source-field" }
quests[41759] = { id = 41759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unerwartete Verbündete", description = "Die Kanalisierung des dämonischen Tors erfordert die Hilfe von jemandem, der die Brennende Legion genau kennt.\n\nIch kenne eine derartige Hexenmeisterin, doch mein Name treibt ihr vermutlich immer noch Schaum vor den Mund. Es wäre wohl besser, wenn Ihr es seid, <der/die> sie um Hilfe bittet.", sourceObjective = "Sprecht mit Kira Zornseele in Azsuna.", completion = "Ritssyn hat Euch geschickt, ja? Mein früherer Mentor erledigt seine Drecksarbeit also immer noch nicht selbst.\n\nJemand von seiner Stellung kann natürlich nicht mit einem angeblichen Mitglied der Arguswacht gesehen werden. Was würden denn die Leute denken?\n\nIch finde es zwar höchst ergötzlich, dass Ritssyn meine Hilfe braucht, aber für liebe Worte und Gefallen gibt es bei mir nichts, {name}.\n\nBei mir wird in Macht und Wissen bezahlt. Wenn Ihr eines der beiden anbieten könnt, können wir uns möglicherweise einigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41760] = { id = 41760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kel'danaths Vermächtnis", description = "Kel'danath hat etwas Unglaubliches entdeckt: die Macht, die Verdorrten zu unterwerfen und sogar zu kontrollieren.\n\nIch mache dort weiter, wo mein alter Freund aufgehört hat. Wir werden dafür sorgen, dass er nicht umsonst gestorben ist.\n\nVielleicht können wir sogar den Elenden, die einem schlimmeren Schicksal als dem Tod überlassen wurden, Frieden verschaffen.\n\nIch benötige weitere Versuchsobjekte. Nehmt Kel'danaths Zauberstein und unterwerft damit weitere Verdorrte.", sourceObjective = "Benutzt den Zauberstein von Kel'danath, um 5 Verdorrte zu bezaubern, und schickt sie nach Shal'Aran.", progress = "Wenn wir Kel'danaths Forschung weiterführen möchten, brauchen wir weitere Versuchsobjekte.", completion = "Faszinierend.\n\nHoffen wir, dass der Zauber hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[41761] = { id = 41761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zusammentreiben der Winterelche", description = "Dieser Hof gehört meinem Vater Karmaan, und unser Viehbestand besteht größtenteils aus Talbuks. Ein Schotling muss das Tor ihres Pferchs geöffnet haben, denn sie sind alle entkommen!\n\nDie kleinen Mistviecher hätten sie direkt im Gehege töten können, doch sie jagen ihre Beute gerne. Ich befürchte, dass ich ihr nächstes Opfer sein werde, wenn ich noch länger hierbleibe!\n\nKönnt Ihr die Talbuks zusammentreiben und herbringen? Ich schaffe es nicht und mein Vater darf nichts davon erfahren!", sourceObjective = "Rettet 4 Talbuks auf Kuuros Hof.", sourceObjectiveStatus = "unverified-source-field" }
quests[41762] = { id = 41762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sympathisanten unter den Shal'dorei", description = "Elisandes Entscheidung, die Legion in Suramar willkommen zu heißen, bescherte ihr eine Menge Feinde, doch nur wenige von uns waren kühn genug, ihr offen zu trotzen.\n\nWir haben Verbündete in der Stadt. Wir wissen nur nicht, wie viele.\n\nIhr müsst einen Zauberfechter namens Silgryn kontaktieren. Er steht hinter unserer Sache und hält sich seit dem gescheiterten Putsch bereit.\n\nEr patrouilliert am westlichen Stadtrand. Sprecht ihn mit Namen an und sagt ihm, dass unsere Sache nicht hoffnungslos ist!", sourceObjective = "Sprecht mit Silgryn am Stadtrand von Suramar.", completion = "Hier sollten wir einen Moment sicher reden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[41763] = { id = 41763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ziel so nahe", description = "Er ist in der Nähe, {race}. Ich fühle es.\n\nWir müssen Shala'nir nach Malfurion absuchen. Wenn wir ihn nicht bald finden, könnte ich ihn für immer verlieren.\n\nAls wir uns das erste Mal trafen, wusste ich nicht, ob man Euch trauen kann. Aber jetzt weiß ich, dass Ihr mich nicht enttäuschen werdet.\n\nIch... danke Euch.", sourceObjective = "Sucht in Shala'nir nach Malfurion.", completion = "Das kann nicht sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[41764] = { id = 41764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In ihren Fußstapfen", description = "Geistwandler wahren das Gleichgewicht zwischen der Welt der Lebenden und dem Geisterreich. Wir können in die Erinnerungen der Toten reisen und so Hinweise auf die Vergangenheit erhalten.\n\nDie von Ebenhorn gepflegten Zauberschutze wurden vor langer Zeit von Helden im Kampf gegen die Finsternis dort platziert. Wenn wir in ihre Fußstapfen treten, können wir vielleicht die Zauberschutze ausfindig machen und reaktivieren.\n\nDer als \"Schuppenschrecken\" bekannte Drogbar Igrul war ein getreuer Freund von Huln Hochberg. Verwendet das Wasser der Vision, um seine Erinnerung zu erleben und den Ort zu finden, an dem er den ersten Zauberschutz platziert hat.", sourceObjective = "Benutzt das Wasser der Vision, um durch die Erinnerungen von Igrul dem Schuppenschrecken zu reisen.", progress = "Als Geistwandler bin ich in der Lage, die Erinnerungen der Toten zu sehen.", completion = "Es freut mich sehr, dass Ihr den ersten Zauberschutz platzieren konntet. Wir sind damit der Rettung von Ebenhorn einen Schritt näher.\n\nAber diese Erwähnung der Finsternis ist beunruhigend. Es ist ein Monster, dass in unseren Mythen, Legenden und Lagerfeuergeschichten erwähnt wird.\n\nAber könnten diese Geschichten vielleicht doch auf etwas Wahrem beruhen?", sourceObjectiveStatus = "unverified-source-field" }
quests[41766] = { id = 41766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildtierschutztrupp", sourceObjective = "Besiegt Rocko in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[41767] = { id = 41767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wagemutige Rettung", description = "Der Plan ist einfach, wird aber einige Mühe von Eurer Seite erfordern.\n\nKira und ich werden das dämonische Tor beschwören, doch Ihr müsst es allein betreten und die vermissten Ratsmitglieder zurückholen.", sourceObjective = "Betretet die Dämonenwelt und rettet die vermissten Ratsmitglieder.", progress = "Kira und ich können das Tor aufrechterhalten, doch Ihr werdet die Dämonenwelt alleine betreten müssen.", completion = "Shinfel darf nicht von Mephistroth in die Knie gezwungen werden. Mit ihrer Macht und ihrem Wissen würde der Schreckenslord einen vernichtenden Angriff gegen die Schreckensnarbe führen.\n\nMit einem Beschwörungsritual sollten wir Shinfel auf unsere Seite holen können, doch müssen wir dazu einen mächtigen Anker schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41768] = { id = 41768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtfeuer der Seele", description = "Ich habe Shinfels Seele in ihren Stab gebunden, damit er als Anker in dieser Welt dienen kann.\n\nWenn wir das Beschwörungsritual durchführen, wird er als Leuchtfeuer fungieren und Shinfel durch den Wirbelnden Nether zurück in unsere Welt geleiten.", sourceObjective = "Führt ein Ritual der Beschwörung durch, um das vermisste Ratsmitglied zu retten.", progress = "Ohne Shinfel kann der Rat nicht neu formiert werden.", completion = "Wir haben Shinfel zwar bei uns, doch ihr Geist gehört immer noch den Dämonen, die sie gefangen genommen haben.\n\nMit welcher uralten Magie haben sie sie verflucht? So etwas habe ich noch nie gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41769] = { id = 41769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ernie, der verrückte Alchemist", description = "Wenn wir diesen Fluch aufheben möchten, müssen wir auf jeden Fall zuerst wissen, um welche Art von Magie es sich handelt.\n\nIch kenne einen Alchemisten, der sich mit seinen ungewöhnlichen Methoden einen ganz schönen Namen gemacht hat. Der verrückte Ernie wurde vor langer Zeit aus Gilneas verstoßen und hat sich, soweit ich weiß, in diesen Landen niedergelassen.\n\nSein Wissen ist vielleicht der erste Schritt, diesen Fluch zu brechen.", sourceObjective = "Sucht Ernie, den verrückten Alchemisten, in Val'sharah.", progress = "Seid Ihr gekommen, um zu helfen? Wir alle müssen unseren Teil beitragen.", completion = "Ich hätte nicht geglaubt, dass ich diesen Namen noch einmal hören würde.\n\nWir haben vielleicht in der Vergangenheit zusammengearbeitet, aber Ritssyn muss wissen, dass ich nicht mehr der Mann bin, der ich einst war.\n\nMarl und ihr Hof haben nun für mich Priorität.", sourceObjectiveStatus = "unverified-source-field" }
quests[41770] = { id = 41770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmel über uns", description = "Seit dem Tode Al'Akirs hat es keinen Windlord gegeben, um die Luftelementare anzuführen.\n\nDas Reich des Himmelswalls ist in Aufruhr versetzt worden. Der Thron von Al'Akir gehört rechtmäßig Donneraan, aber das, was von der Essenz des Prinzen verblieben ist, wird immer schwächer. Wenn wir uns nicht beeilen, könnte Donneraan für immer verloren sein.\n\nBringt die beschädigte Klinge Donnerzorn zum Vortexgipfel und sprecht mit Celestos.\n\nCelestos war ein treuer Diener Al'Akirs und wird Euer Bestreben teilen, Donneraan wiederzubeleben.", sourceObjective = "Sprecht mit Celestos am Vortexgipfel.", completion = "Scharfseher Nobundo hat mir von Eurem Plan, Azeroth zu retten, erzählt. Ich fürchte, ich könnte der einzige Zephyr sein, der Euer Verlangen teilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41771] = { id = 41771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederaufladung der Klinge", description = "Ihr habt die Gesegnete Klinge des Windsuchers entdeckt und mit ihr haltet Ihr alles, das von der Seele Prinz Donneraans geblieben ist, in Händen.\n\nDonnerzorn kann wiederhergestellt werden, aber dafür ist eine seltene Essenz nötig, die man das Herz des Himmelswalls nennt.\n\nVortos, der Herzog der Ostwinde, besitzt das Herz... aber er wird es nicht freiwillig hergeben.\n\nVortos muss besiegt werden, und das Herz des Himmelswalls muss mit der Klinge vereint werden.\n\nNur dann kann Donneraan zurückkehren und den Thron der Vier Winde für sich beanspruchen.", sourceObjective = "Beschafft das Herz des Himmelswalls.", progress = "Habt Ihr das Herz des Himmelswalls beschafft?", completion = "Endlich wird der Windsucher seinen rechtmäßigen Platz als Erbe des Throns der Vier Winde einnehmen. Dies ist ein ruhmreicher Tag für Himmelswall!", sourceObjectiveStatus = "unverified-source-field" }
quests[41772] = { id = 41772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aszendent der Flammen", description = "Es tobt momentan ein endloser Krieg um die Macht über die Feuerlande. Von den beiden aufstrebenden Feuerlords hasst Lord Glimmeron die Sterblichen am wenigsten.\n\nWenn wir ihm helfen, seinen Rivalen zu besiegen, wird er sich im Gegenzug vielleicht mit uns verbünden.\n\nDie Champions des Irdenen Rings haben sich bereits in die Feuerlande begeben. Geht, sucht Rehgar Erdenwut auf und findet einen Weg, aus dem alten Feind einen neuen Verbündeten zu machen.\n\nWenn jemand diese unmöglich erscheinende Aufgabe meistern kann, dann Ihr, <Scharfseher/Scharfseherin>.\n\nMögen die Elemente mit Euch sein.", sourceObjective = "Sprecht mit Rehgar Erdenwut in den Feuerlanden.", completion = "Endlich seid Ihr eingetroffen, Scharfseher {name}.\n\nAnscheinend ist unsere Anwesenheit in den Feuerlanden nicht unbemerkt geblieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[41773] = { id = 41773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl des Feuerlords", description = "Seid gegrüßt, <Sterblicher/Sterbliche>. Ich bin Scaldius, Gesandter von Lord Glimmeron.\n\nIch habe mich gerade mit anderen Mitgliedern Eures Ordens getroffen. Sie sagten mir, dass Ihr den Gegnern meines Meisters ein Ende bereiten wollt. Das gefällt Lord Glimmeron.\n\nPyroth und seine Diener trotzen der Herrschaft meines Meisters und deshalb muss an ihnen ein Exempel statuiert werden. Ihr werdet Pyroth und seine Champions töten!\n\nNichts ist demütigender als der Tod durch einen Sterblichen. Gelingt Euch das, wird Lord Glimmeron Euch eine Audienz gewähren.", sourceObjective = "Besiegt die Streitkräfte von Pyroth.", progress = "Ich werde das Herz von Pyroth mit großer Befriedigung verschlingen!", completion = "Rhyoliths Sohn wurde von einfachen Sterblichen getötet? Welch ein schmachvoller Tod!\n\nIhr habt Euch gut geschlagen, {class}. Das erfüllt mich mit großer Befriedigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[41774] = { id = 41774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rivalen des Feuers", description = "Ihr steht vor dem wahren Herrn der Feuerlande, <Sterblicher/Sterbliche>. Dieses Land gehört rechtmäßig mir, da ich es der Asche von Ragnaros selbst entrissen habe.\n\nAber es gibt da ein paar Narren, die meine Herrschaft infrage stellen. Ich würde ihre wertlosen Seelen mit Freuden auslöschen, aber ich werde ihnen nicht die Ehre gewähren, von meiner Hand getötet zu werden.\n\nFür ihre Unverschämtheit müssen sie gedemütigt werden. Und nichts ist demütigender, als von sterblicher Hand getötet zu werden.\n\nErheitert mich, <Schamane/Schamanin>. Erweist Euch als würdig und vernichtet meine Rivalen!", sourceObjective = "Kehrt mit Garixxias qualmendem Herz und dem Kern der geschmolzenen Wut zu Lord Glimmeron zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[41775] = { id = 41775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Steinmutter", description = "Um die vier Elementarlords von Azeroth zu vereinen, müsst Ihr auch Therazane, die große Steinmutter, aufsuchen und sie davon überzeugen, sich der Sache Azeroths anzuschließen.\n\nAllerdings hat die Steinmutter momentan alle Hände voll damit zu tun, den Wiederaufstieg des Schattenhammers in Tiefenheim niederzuschlagen.\n\nWenn wir Therazane unterstützen, wird sie vielleicht zustimmen, sich mit dem Irdenen Ring gegen die Brennende Legion zusammenzuschließen.\n\nReist zu Therazanes Thron im Herzen von Tiefenheim. Helft ihr, den Schattenhammer zu besiegen, und überzeugt sie davon, mit uns gemeinsam Azeroth zu verteidigen!", sourceObjective = "Sprecht mit Therazane in Tiefenheim.", completion = "Der Irdene Ring ist gekommen, um seine Hilfe anzubieten? Das ist unerwartet... aber dennoch willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41776] = { id = 41776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Windlords", description = "Nachdem der Donnerzorn wieder aufgeladen ist, kann Prinz Donneraan wieder in das Reich des Körperlichen zurückkehren.\n\nIch werde gleich den Geist meines Meisters von der gesegneten Klinge freisetzen.\n\nWenn das Ritual vollendet ist, wird der Himmelswall wieder einen Windlord haben.", sourceObjective = "Ruft Prinz Donneraan herbei.", completion = "Endlich bin ich wieder zurück am Himmelswall, wenn auch dank der Hilfe eines Sterblichen. Ich stehe tief in Eurer Schuld, Scharfseher.", sourceObjectiveStatus = "unverified-source-field" }
quests[41777] = { id = 41777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vernichtung des Kultes", description = "Nur wir können den Schattenhammer noch davon abhalten, Tiefenheim zu erobern.\n\nAzeroth ist einfach nicht imstande, die Mächte des Schattenhammers und der Brennenden Legion gleichzeitig zu bekämpfen. Es liegt an uns, diesen Kult zu vernichten, bevor er sich wieder vollends erheben kann.\n\nBegleitet mich zu ihrer Festung. Zusammen werden wir ihre Reihen nachhaltig ausdünnen!", sourceObjective = "Tötet 15 Kultisten des Schattenhammers am Thron des Zwielichts.", completion = "Der Schattenhammer wird sich von den heutigen Verlusten nicht so schnell erholen. Es war mir eine Ehre, an Eurer Seite zu kämpfen, Scharfseher {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41778] = { id = 41778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schmiede anheizen", description = "Kennt Ihr die Obliterumschmiede? Man kann sie benutzen, um handgefertigte Gegenstände einzuäschern und daraus wertvolles Obliterum zu gewinnen. Ich persönlich bin sehr neugierig, sie einmal in Aktion zu sehen.\n\nEiner meiner vielen Bewunderer hat mir kürzlich eine Abenteurerrobe geschenkt, doch sie steht mir nicht besonders gut.\n\nLegt sie in die Schmiede und seht, was passiert.", sourceObjective = "Benutzt die Obliterumschmiede, um Erzmagier Karlains machtgetränkte seidengewebte Robe einzuäschern.", progress = "Was kam dabei heraus, {name}?", completion = "Erfolg! Auch wenn ihr Geschmack in puncto Inneneinrichtung nicht ganz dem der Architekten von Dalaran entspricht, haben die Dämonenjäger doch eine leistungsstarke Schmiede erschaffen.\n\nBehaltet Ihr das Obliterum, {name}. Ich habe das Gefühl, Ihr werdet es irgendwann brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41780] = { id = 41780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammt!", description = "Mit Flüchen der Verdammnis macht man keine Scherze und selbst die Hexenmeister wollten eine ganze Zeit lang nichts mit ihnen zu tun haben.\n\nDie Magie wird mit der Zeit stärker, was letztendlich zum Tod führt. Nur derjenige, der den Fluch gewirkt hat, kann ihn aufheben.\n\nIch kann ein Elixier brauen, das den Verlauf verlangsamt, doch zunächst müsst Ihr eine Reihe Zutaten sammeln.", sourceObjective = "Sammelt die Zutaten, die Ernest für ein Elixier der Verlangsamung braucht.", progress = "Habt Ihr diese Zutaten schon gefunden? Die Zeit läuft Euch davon, wisst Ihr...", completion = "Das scheint alles zu sein, was ich brauche. Gebt mir nur einen Moment, es zusammenzumischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41781] = { id = 41781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziegen treiben", description = "Falls Ihr es noch nicht bemerkt habt: Es geht hier ein wenig hektisch zu.\n\nMarl leistet ganze Arbeit dabei, die Maisfelder zu schützen, doch das ganze Chaos hat unsere Ziegen aufgeschreckt. Als der Kampf begann, sind sie aus ihrem Gatter gestürmt, und jetzt laufen sie überall herum!\n\nTreibt sie doch bitte für mich zusammen, dann werde ich mein Bestes geben, Euren Fluch in den Griff zu bekommen.", sourceObjective = "Fangt Grauhornziegen ein und bringt sie dann in ihren Pferch zurück.", progress = "Habt ihr meine Ziegen schon gefunden?", completion = "Wie es scheint, ist keine meiner Ziegen verloren gegangen.\n\nDann sehen wir mal, ob wir etwas gegen den Fluch unternehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[41782] = { id = 41782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Hügeln", description = "Es heißt, ein Fragment von Ursocs Geist – seine Wut, sein Zorn – blieb nach seinem Tod in seinen Klauen zurück. Nur wahre Meister der Disziplin haben eine Chance, sie zu nutzen, ohne von der Wut des Bärenfürsten überwältigt zu werden.\n\n<Lea betrachtet Euch einen Moment lang konzentriert.>\n\nAber ich sehe, dass Ihr <kein Anfänger/keine Anfängerin> seid.\n\nNun gut, schöpft Wasser vom Mondbrunnen am nördlichen Rand des Hains und kommt damit zu mir. Ich werde Eure Ankunft am zerbrochenen Stumpf von Vordrassil in Nordend erwarten.", sourceObjective = "Füllt eine Phiole mit Mondbrunnenwasser und sucht Lea Steinpfote in den Grizzlyhügeln auf.", progress = "Habt Ihr das Mondbrunnenwasser? Es ist für unsere Aufgabe von größter Bedeutung!", completion = "Ausgezeichnet! Dieses Wasser brauchen wir, um in den Smaragdgrünen Traum zu gelangen, doch erst müssen wir uns um die magischen Zauberschutze kümmern, welche die Klauen schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41783] = { id = 41783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfergaben der Gefallenen", description = "Als die Klauen verborgen worden sind, wurden magische Zauberschutze errichtet, damit niemand den Ort erreichen konnte. Nur die Macht eines Halbgottes wie Ursocs Bruder Ursol könnte uns einen Weg durch die Zauberschutze bahnen.\n\nUrsol ist ein zurückgezogen lebender Wächter und wird sich uns erst dann zeigen, wenn wir ihm eine Opfergabe darbieten.\n\nWie auch Ursoc wurde er von den Furbolgs verehrt, doch nach vielen Jahren des Krieges gibt es nur noch wenige Stämme und ihre Schamanen sind alle tot.\n\nDurchsucht die Körper der Gefallenen nach Opfergaben, während ich den Schrein vorbereite.", sourceObjective = "Durchsucht die Leichen von Schamanen der Frostpfoten nach Opfergaben für Ursol und kehrt damit zu Lea Steinpfote in Grauschlund zurück.", progress = "Habt Ihr die Opfergaben beschafft?", completion = "Ja, das sollte klappen!\n\nIch durchwühle die Taschen der Toten nur ungern, doch wir brauchen die Sachen dringender als sie.\n\nFangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[41784] = { id = 41784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit schinden", description = "Lasst Euch von dem Geruch nicht täuschen, dieses Gebräu ist so gut wie ungiftig.\n\nWer auch immer an den Symptomen leidet, soll den gesamten Inhalt der Phiole trinken, bis zum letzten Tropfen! Wenn das Elixier wirkt, sollte man das sofort bemerken. Wenn nicht, nun... Sagt demjenigen einfach nur, er trinkt es auf eigenes Risiko, verstanden?\n\nDenkt daran, dass dies den Fluch nur schwächt und nicht heilt.", sourceObjective = "Gebt Shinfel Pestschwur das Elixier der Verlangsamung.", progress = "Shinfels Fluch wird sie bald umbringen, wenn wir keine Möglichkeit finden, seinen Fortschritt zu verlangsamen.", completion = "Einen Dämon zu töten, ist nicht immer die Antwort. Manchmal besteht die Lösung darin, einen zu kontrollieren... Das Gleiche gilt auch für zwei.\n\nWenn wir die Schwestern beschwören und ihren Willen beugen können, wäre das ein vernichtender Schlag gegen Mephistroths Streitkräfte und würde Shinfel von ihrem Fluch befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[41785] = { id = 41785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Zischknall", description = "Ich habe Grund zu der Annahme, dass Wilfred Zischknalls Schwester sich nach Sturmheim begeben hat.\n\nWenn sie auch nur halb so mächtig ist wie er, dafür aber mindestens doppelt so intelligent, dann schaffen wir es vielleicht tatsächlich, die Eredarzwillinge zu beschwören.", sourceObjective = "Sucht nach Lulubell Zischknall in Sturmheim.", completion = "Ihr seid der neue Anführer des Rates, nicht wahr? Das sehe ich an Eurer Waffe. Ihr habt bestimmt eine fabelhafte Geschichte dazu, wie Ihr sie bekommen habt.\n\nIch heiße Lulubell, oder einfach Lulu. Aber... ich, äh, mir wäre es lieb, wenn Ihr niemandem sagt, dass Ihr mich gesehen habt, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[41786] = { id = 41786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Sea Giant King - twh" }
quests[41787] = { id = 41787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anderer Leute Dreck", description = "Ein Geständnis allein reicht nicht aus, um mich zu rehabilitieren. Solange diese Dämonen hier herumlaufen, werde ich für ihre Anwesenheit verantwortlich gemacht.\n\nJemand muss sich um den Dreck kümmern, den dieser Hexenmeister hinterlassen hat. Ich würde es ja selbst tun, darf mich aber nicht am Ort des Geschehens sehen lassen.\n\nIhr könntet sie allerdings verbannen. Das würde schon ausreichen. Verwendet diese Kugel, um gerade beschworene Dämonen dahin zurückzuschicken, wo sie herkamen. Und zwar für immer!", sourceObjective = "Verbannt Dämonen, die leichtsinnigerweise in Sturmheim beschworen wurden.", completion = "Vielen Dank, {name}.\n\nEure Hilfsbereitschaft gegenüber einer Ausgestoßenen wird nicht vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41788] = { id = 41788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geständnis erzwingen", description = "Mein Aufenthaltsort muss geheim bleiben, zumindest, bis ich Beweise für meine Unschuld habe.\n\nNur wegen meines Familiennamens werde ich jedes Mal beschuldigt, wenn so ein nichtsnutziger Hexenmeister Dämonen beschwört, die er nicht beherrschen kann.\n\nDer Ort meines letzten \"Verbrechens\" ist eine Höhle in der Nähe. Dort laufen wilde Wichtel und andere niederträchtige Dämonen frei herum.\n\nFindet den miesen Hexenmeister, der dafür verantwortlich ist, und lasst ein Geständnis von ihm unterzeichnen.", sourceObjective = "Sucht den Hexenmeister, der verantwortungslos Dämonen beschworen hat, und besorgt ein schriftliches Geständnis seiner Vergehen.", completion = "Die Schrift ist ein wenig schwer zu lesen, aber ich glaube, die wichtigen Informationen sind alle da.\n\nMit diesem Geständnis sollte ich meine Unschuld beweisen und mich wieder wichtigeren Dingen zuwenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[41789] = { id = 41789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Felsen" }
quests[41790] = { id = 41790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursols erste Prüfung", description = "Die Legion...\n\n<Das Leuchten in Ursols Augen wird immer heller.>\n\nJa... ich kann mich noch genau erinnern, wie mein Bruder vor langer Zeit sein Leben ließ. Seine Klauen kosteten unzählige Dämonen das Leben, bevor sie ihn in enormer Überzahl schließlich niederstreckten. Mein Bruder verkörperte den wahren Geist des Bären!\n\nIhr müsst mir beweisen, dass auch in Euch der Geist des Bären wohnt.", sourceObjective = "Schließt Ursols erste Prüfung ab.", progress = "<Der Ahne starrt Euch erwartungsvoll an.>", completion = "Ihr seid durchaus mächtig, doch Stärke allein wird mich nicht beeindrucken.", sourceObjectiveStatus = "unverified-source-field" }
quests[41791] = { id = 41791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursols zweite Prüfung", description = "Ursoc hat nie einen Kampf gescheut, selbst dann nicht, wenn er sich zahllosen Feinden gegenübersah. Wenn Ihr seine Klauen an Euch nehmen wollt, müsst Ihr mir beweisen, dass auch Ihr über derartigen Mut verfügt.\n\nFür Eure nächste Prüfung müsst Ihr Euch dem Ansturm meiner Anhänger stellen. Besiegt alle Geister und zeigt mir, dass Ihr den Mut des Bären besitzt!", sourceObjective = "Schließt Ursols zweite Prüfung ab.", progress = "<Der Ahne starrt Euch erwartungsvoll an.>", completion = "Gut gemacht, {name}. Euer Handeln zeugt von Ehre!\n\nBis jetzt habt Ihr Euch gut geschlagen. Doch bevor ich Euch meinen Segen gebe, erwartet Euch noch eine letzte Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[41792] = { id = 41792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursols dritte Prüfung", description = "Ihr habt Eure Stärke und Euren Mut unter Beweis gestellt. Aber tragt Ihr auch die Bereitschaft in Euch, Euer Letztes zu geben, wenn es wirklich darauf ankommt?\n\nDas wird uns diese letzte Prüfung zeigen.", sourceObjective = "Schließt Ursols dritte Prüfung ab.", progress = "<Der Ahne starrt Euch erwartungsvoll an.>", completion = "Ihr habt all meine Prüfungen siegreich bestanden. Ihr seid wahrlich des Erbes meines Bruders würdig und habt Euch meinen Segen verdient!\n\nGeht nun, findet die Klauen und beansprucht sie als Euer Eigentum.", sourceObjectiveStatus = "unverified-source-field" }
quests[41793] = { id = 41793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leih-Lulubell", description = "Was Ihr da vorhabt, ist ganz schön riskant, wisst Ihr? Eine Schwester zu beschwören, wäre ja schon schwer genug, aber beide gleichzeitig? Da bettelt Ihr förmlich um Ärger.\n\nZum Glück kann ich es mit dieser Herausforderung aufnehmen. Ich helfe Euch und dem Rest des Rats, diese Dämonen zu beschwören, und mache dem Namen Zischknall damit hoffentlich wieder alle Ehre.", sourceObjective = "Sprecht mit Ritssyn Flammengroll.", completion = "Mit Lulubells Hilfe sollten wir die Beschwörung vollenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[41794] = { id = 41794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenpirscher" }
quests[41795] = { id = 41795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörung der Schwestern", description = "Die Beschwörung führen wir am besten in den Randgebieten der Schreckensnarbe durch. Wenn dann etwas schiefgeht, sind die Folgen wenigstens auf eine kleine Insel beschränkt, die über unserem Orden schwebt.\n\nSobald Ihr die Schwestern beschworen habt, benutzt den Blutstein, um sie zu versklaven.\n\nIch sage den anderen, dass es Zeit ist zu beginnen.", sourceObjective = "Reist durch das dämonische Tor, um die Beschwörungsplattform zu erreichen und benutzt den Blutstein, um die Eredarschwestern zu unterwerfen, sobald die Beschwörung abgeschlossen ist.", completion = "Ihr habt es geschafft, {name}. Die Dämonenzwillinge stehen unter Eurer Kontrolle.\n\nSeit dem Fall von Ragnaros habe ich solche Macht nicht zu sehen bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41796] = { id = 41796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sechs sollen es sein", description = "Nachdem Ihr nun die Dämonenschwestern beherrscht, konntet Ihr Mephistroths Heer schwächen und mächtige Verbündete für den Rat heranholen.\n\nWir sind hier jedoch noch nicht fertig. Die Schreckensnarbe wird weiterhin ein Angriffsziel bleiben, solange es die Brennende Legion gibt.\n\nWenn wir unser neues Zuhause beschützen wollen, müssen wir den Rat wiederherstellen. Lulubell wie auch Kira hätten es verdient, sich uns anschließen zu dürfen, aber es gibt nur noch einen freien Platz.\n\nAls <Erster/Erste> der Schwarzen Ernte habt Ihr die Wahl.", sourceObjective = "Entscheidet, wer das letzte Ratsmitglied sein soll.", progress = "Die Wahl ist womöglich nicht einfach. Doch es ist Eure Wahl.", completion = "Die Entscheidung ist also gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41797] = { id = 41797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Truppen", description = "Wie ihr Name vermuten lässt, ist Wichtelmutter Dyala in der Beschwörung von Wichteln sehr bewandert.\n\nSolange der Rat die Schreckensnarbe kontrolliert, werden uns ihre Dienste zur Verfügung stehen.\n\nSprecht mit ihr, wenn Ihr ein Rudel Wichtel ausbilden wollt.", sourceObjective = "Sprecht mit Wichtelmutter Dyala und bildet ein Rudel Wichtel aus.", progress = "Wie ist die Ausbildung verlaufen?", completion = "Ausgezeichnet. Diese Trupps werden bei der Verteidigung der Verheerten Inseln unschätzbare Dienste leisten. Ihr könnt sie genauso auf Missionen schicken wie die Champions.", sourceObjectiveStatus = "unverified-source-field" }
quests[41798] = { id = 41798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung weiterer Truppen", description = "Als <Erster/Erste> des Rates verfügt Ihr über Akolythen, die nach besten Kräften aushelfen, wo sie nur können. Rekrutierer Jared überprüft alle Anwärter auf ihre Tauglichkeit und wählt nur die aus, deren Fähigkeiten wir benötigen.\n\nSprecht am besten sofort mit ihm.", sourceObjective = "Sprecht mit Rekrutierer Jared.", completion = "Ich bin hier, um Euch beim Aufbau einer Armee zu helfen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41799] = { id = 41799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vasallen der Finsternis", description = "Oenia Himmelshorn war ein legendärer Häuptling ihres Stammes. Sie ist zwar schon vor langer Zeit in das Geisterreich gegangen, aber ihre Präsenz ist immer noch allgegenwärtig.\n\nEbenhorn hat mir erzählt, dass Oenia hier einen Zauberschutz platziert hat, um die Leute zu schützen, die ihr so am Herzen lagen... vielleicht vor dem Gespenst der Finsternis.\n\nVerwendet das Wasser der Vision, um in ihr Echo zu reisen. Ihr müsst nicht fürchten, ihre Ruhe zu stören. Eine Heldin wie Oenia würde jede Gelegenheit nutzen, um uns in der Gegenwart zu helfen.", sourceObjective = "Benutzt das Wasser der Vision, um durch die Erinnerungen von Oenia Himmelshorn zu reisen.", progress = "Die Geister sprechen von der Finsternis. Es droht eine große Gefahr, {name}.", completion = "Die Schatten des Geisterreichs werden zunehmend stärker. Ich fürchte, dass sie schon bald in die Realität vorstoßen könnten.\n\nIch bete, dass wir durch die Reaktivierung der Zauberschutze das Schlimmste verhindern können.", sourceObjectiveStatus = "unverified-source-field" }
quests[41800] = { id = 41800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diener der Finsternis", description = "Die Helden der Vergangenheit des Hochbergs haben Zauberschutze platziert, um unser Land vor den heimtückischen Alten Göttern zu schützen. Dank der Umsicht der edlen Champions konnten wir Tausende Jahre Sicherheit genießen.\n\nWir müssen in ihrem Gedenken handeln.\n\nHuln Hochberg selbst hat hier auf der Schneeblinden Hochebene einen Zauberschutz platziert. Er muss reaktiviert werden, wenn wir Ebenhorn retten wollen.\n\nBetretet das Echo von Hulns Geist und lasst Euch durch seine Tapferkeit zu seinem Zauberschutz leiten.", sourceObjective = "Benutzt das Wasser der Vision, um durch die Erinnerungen von Huln Hochberg zu reisen.", completion = "Huln hat gegen die Nekrodunklen gekämpft?\n\nUm Huln ranken sich so viele Legenden, dass ich diese Drogbar nur für eine weitere Geschichte hielt. Aber offensichtlich haben sie der Finsternis gedient.\n\nEine beunruhigende Entdeckung... Aber wir haben jetzt keine Zeit, darüber zu grübeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[41802] = { id = 41802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pforte der Tapferkeit", description = "Nicht viele wissen, dass man auf den Terrassen vor den Hallen der Tapferkeit der Vrykul viele uralte Artefakte finden kann. Dass sich da gerade ein Haufen Dämonen rumtreibt, ist natürlich nicht sehr hilfreich.\n\nNa ja, wir haben wohl keine große Wahl. Wenn die Scheibe sonst nirgends in Sturmheim aufzutreiben ist, muss sie wohl bei der Pforte der Tapferkeit zu finden sein. Viel Glück, {name}.", sourceObjective = "Sucht bei der Pforte der Tapferkeit in Sturmheim nach 6 beschädigten Titanenscheibenfragmenten.", progress = "Ihr seid zurück... und gänzlich unversehrt. Habt Ihr Neuigkeiten?", completion = "Na, dann lasst mich mal sehen.\n\n<Brann untersucht die Scheibenfragmente.>\n\nSchaut Euch das an. Da ist irgendein Teufelszeug dran. Schätze, das hat die ganzen Wichtel hierhergelockt.\n\nIch überlass das mal Euch. Entsorgt es oder macht damit, was immer Ihr eben damit macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[41803] = { id = 41803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gefallen", description = "Caria Teufelsseele war eine herausragende Schülerin... und eine Verräterin, die nun der Legion dient.\n\nAls Belohnung für ihren Verrat hat sie die Kriegsklingen der Aldrachi erhalten, die seelenzerfetzenden Klingen des größten Champions der Aldrachi, der sich am Ende nur Sargeras selbst geschlagen geben musste.\n\nWir haben einen kleinen Spähtrupp entsandt, um nach Caria zu suchen, aber wir haben seitdem nichts mehr von ihnen gehört. Jace verfügt über einen Legionskommunikator, mit dem man vielleicht Kontakt zu ihnen aufnehmen kann. Allerdings benötigen wir dazu eine Energiequelle.\n\nKönntet Ihr vielleicht Khadgar fragen, ob er uns helfen kann? Wir haben leider nicht allzu viele Freunde auf dieser Welt.", sourceObjective = "Fragt Khadgar nach einer Energiequelle für den Legionskommunikator.", completion = "Es ist schön, Euch wiederzusehen. Wenn ich Euch irgendwie dabei helfen kann, die Legion zu bekämpfen, lasst es mich einfach wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41804] = { id = 41804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittet und Euch soll gegeben werden", description = "Ein Legionskommunikator? Hm...\n\n<Khadgar denkt einen Augenblick lang nach.>\n\nIch glaube, ich habe da oben in meiner Schließkiste etwas, das Euch helfen könnte.", sourceObjective = "Lasst Euch eine kristallisierte Seele von Erzmagier Khadgar aushändigen.", progress = "Freunden helfe ich immer gern.", completion = "Ihr müsst mir nicht danken. Aber versprecht mir, dass Ihr hier in der Stadt nichts versehentlich in die Luft jagt. Unsere aktuellen Reparaturkosten sind ohnehin schon gewaltig.", sourceObjectiveStatus = "unverified-source-field" }
